import java.text.DecimalFormat;
import java.util.Scanner;
public class JWinPercentageWonEqual {
	public static void main(String[] args) {
		//Khatwa 1: Ta'reef wa tabteet al-mutaghayyir l-khizan 3adad al-mubarayat al-kamil fi al-dawra
		int totalGames = 12;
		//Khatwa 2: Qira'at 3adad al-mubarayat allati faza biha al-fariq fi al-dawra
		Scanner scan = new Scanner(System.in);
		System.out.println("Adkhil 3adad al-mubarayat allati faza biha al-fariq fi al-dawra: ");
		int wins = scan.nextInt();		
		//Khatwa 3: Tashkik al-madkhul min al-mustakhdim li-3adad al-afaaz, wa talab madkhul salih ma damaa adkhal al-mustakhdim raqam gheer salih; illa dhalik tawqaf
		while ( wins < 0 || wins > totalGames ) {
			System.out.println("Adkhil 3adad al-mubarayat allati faza biha al-fariq fi al-dawra: ");
			wins = scan.nextInt();
		}
		//Khatwa 4: Qira'at 3adad al-mubarayat al-lati tasawa fiha al-fariq fi al-dawra
		System.out.println("Adkhil 3adad al-mubarayat al-musawiya: ");
		int ties = scan.nextInt();		
		//Khatwa 5: Tashkik madkhul al-mustakhdim li-3adad al-mubayat al-musawiya, wa talab madkhul salih ma daa adkhal raqam gheer salih; illa dhalik tawqaf
		while ( ties < 0 || totalGames < (ties + wins) ) {
			System.out.println("Adkhil 3adad al-mubarayat al-musawiya: ");
			ties = scan.nextInt();
		}
		scan.close();
		//Khatwa 6: Ihsab wa tiskhit nisbat al-mubarayat al-mafouza min al-fariq, bi-ihtisab al-mubayat al-musawiya ka nusf fawz
		double ratio = (double) ( wins + ties / 2) / totalGames;
		DecimalFormat fmt = new DecimalFormat("0.###");
		System.out.println("Nisbat al-fawz:" + fmt.format(ratio));
	}
}
